import{_ as e,o as a,c as i,ae as n}from"./chunks/framework.DK2I2JUh.js";const k=JSON.parse('{"title":"Compiler Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/compiler.md","filePath":"advanced/compiler.md"}'),t={name:"advanced/compiler.md"};function l(p,s,o,c,d,r){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="compiler-architecture" tabindex="-1">Compiler Architecture <a class="header-anchor" href="#compiler-architecture" aria-label="Permalink to &quot;Compiler Architecture&quot;">​</a></h1><p>SafeC compiles <code>.sc</code> source files to native executables via LLVM IR. The compiler is a single-pass frontend with no runtime injection — what you write is what gets compiled.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline {#pipeline}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source (.sc)</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>Preprocessor --- #include, #define, #ifdef, #pragma once</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>Lexer --- tokenization with SafeC keyword set</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>Parser --- recursive-descent, C grammar + SafeC extensions</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>AST</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>Semantic Analysis --- name resolution, type checking, region escape analysis</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>Const-Eval Engine --- evaluate const/consteval at compile time</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>Code Generation --- LLVM IR with region metadata (noalias, nonnull, etc.)</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>LLVM Backend --- object code / bitcode</span></span></code></pre></div><p>No runtime injection phase. No implicit transformation inserting hidden allocations.</p><h2 id="key-design-decisions" tabindex="-1">Key Design Decisions <a class="header-anchor" href="#key-design-decisions" aria-label="Permalink to &quot;Key Design Decisions {#key-design-decisions}&quot;">​</a></h2><p><strong>References lower to raw pointers.</strong> A <code>&amp;stack T</code> or <code>&amp;heap T</code> becomes a plain LLVM <code>ptr</code> annotated with <code>noalias</code>, <code>nonnull</code>, and <code>dereferenceable</code> attributes. There is no fat pointer, no reference counting, no hidden indirection.</p><p><strong>Regions are compile-time only.</strong> Region annotations (<code>&amp;arena&lt;R&gt; T</code>) drive escape analysis and borrow checking during semantic analysis. Zero region metadata survives into the generated IR.</p><p><strong>Const globals are folded.</strong> The const-eval engine evaluates <code>const</code> and <code>consteval</code> initializers at compile time. The results are written back as literal IR constants — no runtime initialization code is emitted.</p><p><strong><code>if const</code> is dead-code-eliminated.</strong> Branches guarded by <code>if const</code> are resolved during const-eval. Only the taken branch survives into codegen.</p><p><strong><code>consteval</code> is enforced.</strong> A <code>consteval</code> function called in a runtime context is a compile error, not a silent fallback.</p><p><strong>Struct layout follows C ABI.</strong> SafeC structs are layout-compatible with C structs. No vtable, no hidden fields, no padding surprises.</p><h2 id="source-layout" tabindex="-1">Source Layout <a class="header-anchor" href="#source-layout" aria-label="Permalink to &quot;Source Layout {#source-layout}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>compiler/</span></span>
<span class="line"><span>├── include/safec/</span></span>
<span class="line"><span>│   ├── Token.h          Keyword and token definitions</span></span>
<span class="line"><span>│   ├── Lexer.h          Tokenizer interface</span></span>
<span class="line"><span>│   ├── AST.h            All AST node types</span></span>
<span class="line"><span>│   ├── Type.h           Type representation (primitives, references, regions)</span></span>
<span class="line"><span>│   ├── Parser.h         Recursive-descent parser</span></span>
<span class="line"><span>│   ├── Sema.h           Semantic analysis (scope, types, borrow checking)</span></span>
<span class="line"><span>│   ├── ConstEval.h      Compile-time evaluation engine</span></span>
<span class="line"><span>│   ├── CodeGen.h        LLVM IR generation</span></span>
<span class="line"><span>│   ├── Preprocessor.h   Macro expansion and conditional compilation</span></span>
<span class="line"><span>│   ├── CHeaderImporter.h  Native C header import via clang AST</span></span>
<span class="line"><span>│   ├── Clone.h          AST deep-clone for generics monomorphization</span></span>
<span class="line"><span>│   └── Diagnostic.h     Error/warning reporting</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── Preprocessor.cpp</span></span>
<span class="line"><span>│   ├── CHeaderImporter.cpp</span></span>
<span class="line"><span>│   ├── Lexer.cpp</span></span>
<span class="line"><span>│   ├── AST.cpp</span></span>
<span class="line"><span>│   ├── Type.cpp</span></span>
<span class="line"><span>│   ├── Parser.cpp</span></span>
<span class="line"><span>│   ├── Sema.cpp</span></span>
<span class="line"><span>│   ├── Clone.cpp</span></span>
<span class="line"><span>│   ├── ConstEval.cpp</span></span>
<span class="line"><span>│   ├── CodeGen.cpp</span></span>
<span class="line"><span>│   └── main.cpp</span></span>
<span class="line"><span>├── examples/            demo files</span></span>
<span class="line"><span>└── CMakeLists.txt</span></span></code></pre></div><h2 id="building-the-compiler" tabindex="-1">Building the Compiler <a class="header-anchor" href="#building-the-compiler" aria-label="Permalink to &quot;Building the Compiler {#building-the-compiler}&quot;">​</a></h2><p>SafeC requires LLVM 21+ and CMake:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compiler</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DLLVM_DIR=/path/to/llvm/lib/cmake/llvm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The resulting binary is <code>build/safec</code>.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Compile to executable (via LLVM IR + clang link) — the two-step form</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-llvm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.ll</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.ll</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or in one step, via --emit-bin (see &quot;Linking&quot; below)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Dump the AST</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-ast</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable the (on-by-default) incremental bitcode cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-incremental</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Debug info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lines</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # line-level debug info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # full variable-level debug info</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cross-compile to another architecture/OS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-unknown-linux-gnu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-llvm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.ll</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Print the compiler version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="linking-emit-bin" tabindex="-1">Linking (<code>--emit-bin</code>) <a class="header-anchor" href="#linking-emit-bin" aria-label="Permalink to &quot;Linking (\`--emit-bin\`) {#linking-emit-bin}&quot;">​</a></h2><p><code>safec</code>&#39;s own pipeline stops at LLVM IR/bitcode — it never links on its own. <code>--emit-bin</code> adds a genuine &quot;compile straight to a native binary/library&quot; mode: it writes the module to a temporary <code>.ll</code> file, then invokes the system <code>clang</code> (assemble + link) or <code>ar</code> (for a static archive) to produce the file at <code>-o</code>. This is the same tool-shelling approach <a href="/safec-docs/advanced/safeguard.html"><code>safeguard</code></a> already uses per source file — <code>--emit-bin</code> just makes it available directly from <code>safec</code> for a single <code>.sc</code> file, without going through a project/<code>Package.toml</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Link a plain executable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Link against an external library: -l&lt;name&gt; / -L&lt;dir&gt;, same convention as</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># clang/gcc. Calling into a C library needs a matching &#39;extern&#39; declaration</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># on the SafeC side (see C Interop); calling into C++/Objective-C needs</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &#39;extern &quot;C&quot;&#39; on *their* side to avoid name mangling — SafeC itself has no</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># name mangling to opt out of, since every top-level function already has</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a plain C-compatible symbol name.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L/usr/local/lib</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Produce a shared/dynamic library instead of an executable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mathlib.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --shared</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libmath.dylib</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Produce a static library (an &#39;ar&#39; archive of the compiled object — no</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># linker, -l/-L are meaningless here since a .a isn&#39;t linked, just packaged)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mathlib.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --static-lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libmath.a</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable LTO for the link step (thin is the default; full is also available)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lto</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lto=full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Release profile: -O2 unless -O was given explicitly</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/safec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.sc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p><code>-l</code>/<code>-L</code>/<code>--shared</code>/<code>--static-lib</code>/<code>--lto</code> are only meaningful with <code>--emit-bin</code> — passing them without it prints a warning and has no effect, since there&#39;s no link step for them to configure. <code>SAFEC_CLANG</code>/<code>SAFEC_AR</code> environment variables override the discovered <code>clang</code>/<code>ar</code> path, mirroring <code>safeguard</code>&#39;s <code>SAFEC_CLANG</code>/<code>SAFEC_CLANGXX</code>.</p><h2 id="multi-target-codegen" tabindex="-1">Multi-Target Codegen <a class="header-anchor" href="#multi-target-codegen" aria-label="Permalink to &quot;Multi-Target Codegen {#multi-target-codegen}&quot;">​</a></h2><p><code>--target &lt;triple&gt;</code> cross-compiles to any LLVM-registered target — the compiler hardcodes nothing architecture-specific; <code>--target</code> selects an LLVM <code>TargetMachine</code>, which supplies both the data layout (used live during codegen for <code>sizeof</code>/struct layout/alignment) and the instruction selection a later <code>llc</code>/<code>clang -c</code> step uses to turn the emitted IR into real machine code. Omit the flag to target the host, unchanged from before this flag existed.</p><p>Verified with real generated machine code (not merely accepted input) across:</p><table tabindex="0"><thead><tr><th>OS</th><th>Architectures</th></tr></thead><tbody><tr><td>macOS</td><td>x86_64, AArch64</td></tr><tr><td>Linux</td><td>x86_64, x86, AArch64, Aarch32 (ARMv7), RV64, RV32</td></tr><tr><td>Windows (MSVC)</td><td>x86_64, x86, AArch64</td></tr><tr><td>iOS</td><td>AArch64 (device + simulator)</td></tr><tr><td>Android</td><td>AArch64, Aarch32, x86_64, x86</td></tr><tr><td>FreeBSD</td><td>x86_64, AArch64</td></tr><tr><td>Bare metal (<code>--target=&lt;alias&gt;</code>)</td><td>x86, x86-64, AArch32, AArch64, Thumb, Thumb-2, Cortex-M (ARMv6-M, v7-M, v7E-M, v8-M), RV32I/E, RV64I/E — see <a href="/safec-docs/reference/baremetal.html#targets">Bare-Metal Targets</a></td></tr><tr><td>Portable / GPU</td><td>WebAssembly, SPIR-V, CUDA (NVPTX), ROCm (AMDGPU)</td></tr></tbody></table><p>Metal Shading Language is not reachable via <code>--target</code> — Apple&#39;s Metal compiler has no LLVM backend upstream, unlike NVPTX/AMDGPU/SPIR-V, which are real LLVM targets. The only interop path from SPIR-V output is a third-party translator (e.g. SPIRV-Cross), not something <code>safec</code> does.</p><p>Target-related flags: <code>--target=&lt;alias|triple&gt;</code>, <code>--target-cpu</code>, <code>--target-features</code>, <code>--target-abi</code>, <code>--list-targets</code>, <code>--print-target-clang-flags</code>, and <code>--provides=&lt;fn,...&gt;</code> (functions another translation unit defines, which silences the freestanding hosted-call warning for them).</p><p>See <a href="/safec-docs/stdlib/simd.html"><code>std::simd</code></a> for the SIMD library built on top of this, and <a href="/safec-docs/reference/baremetal.html">Bare-Metal</a> for ARM Cortex-M specifics (HAL, DSP-extension intrinsics, MVE).</p><h2 id="incremental-compilation" tabindex="-1">Incremental Compilation <a class="header-anchor" href="#incremental-compilation" aria-label="Permalink to &quot;Incremental Compilation {#incremental-compilation}&quot;">​</a></h2><p>The file-level bitcode cache is <strong>on by default</strong> (optional <code>--cache-dir &lt;dir&gt;</code>, defaulting to <code>.safec_cache</code>; disable with <code>--no-incremental</code>). The compiler hashes the preprocessed source together with the compiler binary&#39;s own identity (so a rebuilt compiler always misses stale entries) and every codegen-affecting flag — <code>--target</code>, <code>-g</code>, <code>--freestanding</code>, <code>--no-strict-aliasing</code> — using FNV-1a. If a cached <code>.bc</code> file with a matching hash exists, all pipeline stages are skipped.</p><p>On a cache miss, the full pipeline runs and the resulting bitcode is written to the cache directory.</p><p>Use <code>--clear-cache</code> to delete all cached <code>.bc</code> files.</p><h2 id="debug-info" tabindex="-1">Debug Info <a class="header-anchor" href="#debug-info" aria-label="Permalink to &quot;Debug Info {#debug-info}&quot;">​</a></h2><p>SafeC supports two levels of DWARF debug information:</p><table tabindex="0"><thead><tr><th>Flag</th><th>What it emits</th></tr></thead><tbody><tr><td><code>--g lines</code></td><td><code>DICompileUnit</code> + <code>DIFile</code> + <code>DISubprogram</code> per function + <code>DILocation</code> per statement</td></tr><tr><td><code>--g full</code></td><td>Everything in <code>lines</code> + <code>DILocalVariable</code> + <code>dbg.declare</code> per local variable</td></tr></tbody></table><p>No <code>--g</code> flag means no debug metadata is emitted.</p><h2 id="native-c-header-import" tabindex="-1">Native C Header Import <a class="header-anchor" href="#native-c-header-import" aria-label="Permalink to &quot;Native C Header Import {#native-c-header-import}&quot;">​</a></h2><p><code>#include &lt;stdio.h&gt;</code> works natively in SafeC. The <code>CHeaderImporter</code> module invokes <code>clang -ast-dump=json</code> on the included header, then extracts <code>FunctionDecl</code> and <code>TypedefDecl</code> nodes into SafeC&#39;s AST.</p><p>Unsupported constructs (function pointers, ObjC blocks, <code>long double</code>, <code>__int128</code>) are silently skipped. Enum typedefs are lowered to <code>typedef int name</code>.</p><p>This can be disabled with <code>--no-import-c-headers</code>.</p><h2 id="generics-monomorphization" tabindex="-1">Generics Monomorphization <a class="header-anchor" href="#generics-monomorphization" aria-label="Permalink to &quot;Generics Monomorphization {#generics-monomorphization}&quot;">​</a></h2><p>Generic functions (<code>generic&lt;T&gt;</code>) are monomorphized at compile time. When the compiler encounters a call to a generic function, it:</p><ol><li>Infers the type argument <code>T</code> from the call-site argument types</li><li>Deep-clones the function AST via <code>Clone.cpp</code>, substituting <code>T</code> with the concrete type</li><li>Appends the monomorphized function (mangled as <code>__safec_fn_type</code>) to the translation unit</li><li>Runs semantic analysis and codegen on the monomorphized copy</li></ol><p>Generic function bodies are skipped during the first semantic analysis pass — they are only analyzed after monomorphization.</p><h2 id="const-eval-engine" tabindex="-1">Const-Eval Engine <a class="header-anchor" href="#const-eval-engine" aria-label="Permalink to &quot;Const-Eval Engine {#const-eval-engine}&quot;">​</a></h2><p>The const-eval engine is a tree-walking interpreter that runs at compile time. It handles:</p><ul><li><code>const</code> global initializers</li><li><code>consteval</code> function bodies</li><li><code>static_assert</code> verification</li><li><code>if const</code> branch selection</li></ul><p>Evaluated results are folded back into the AST as <code>IntLit</code> or <code>FloatLit</code> nodes, so codegen sees only literal constants.</p>`,51)])])}const g=e(t,[["render",l]]);export{k as __pageData,g as default};
